import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.for-each.js";
/* eslint-disable */
import { list_cabinet_root_folders } from "@/graphql/queries.js";
import { API, graphqlOperation } from "aws-amplify";
import SnackBar from "@/components/SnackBar.vue";
import RequestAccess from "@/components/NewCabinet/RequestAccess.vue";
export default {
  components: {
    SnackBar,
    RequestAccess
  },
  data() {
    return {
      headers: [{
        title: "Folder",
        value: "Key",
        sortable: false
      }, {
        title: "Description",
        value: "folder_description",
        sortable: false
      }, {
        title: "Created By",
        value: "folder_created_by_name",
        sortable: false
      }, {
        title: "Actions",
        value: "actions",
        sortable: false
      }],
      tableData: [],
      tableLoading: false,
      SnackBarComponent: {},
      requestAccessDialog: false,
      componentCheck: 0,
      rowInfo: {},
      currentPage: 1,
      pageCount: 1,
      itemsPerPage: 20,
      totalCount: 0,
      paginatedItems: [],
      windowHeight: 0
    };
  },
  created() {
    this.fetch_root_folders();
    this.windowHeight = window.innerHeight - 250;
  },
  computed: {
    visiblePages() {
      const pages = [];
      const start = Math.max(1, this.currentPage - 2);
      const end = Math.min(this.pageCount, this.currentPage + 2);
      for (let i = start; i <= end; i++) {
        pages.push(i);
      }
      return pages;
    }
  },
  watch: {
    currentPage() {
      this.updatePageItems();
    }
  },
  methods: {
    async fetch_root_folders() {
      this.tableLoading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(list_cabinet_root_folders, {
          input: {
            organization_id: data.organization.organization_id
          }
        }));
        this.tableData = [];
        this.tableLoading = false;
        var response = JSON.parse(result.data.list_cabinet_root_folders);
        let restrictedCabinets = [];
        let arraynew = [];
        if (response.Status == "SUCCESS") {
          restrictedCabinets = response.data;
          restrictedCabinets.forEach(element => {
            if (element.folder_visibility.visible_type == "RESTRICTED_MEMBERS" && element.folder_created_by_email != this.$store.getters.GetUserObj.user.user_email_id) {
              arraynew.push(element);
              this.tableData = arraynew.filter(item => !item.folder_visibility.visible_members.includes(this.$store.getters.GetUserObj.user.user_id));
            }
          });
          //   this.tableData = response.data;
          //   console.log(response);
        }
        this.totalCount = this.tableData.length;
        this.pageCount = Math.ceil(this.totalCount / this.itemsPerPage);
        this.paginatedItems = this.tableData.slice((this.currentPage - 1) * this.itemsPerPage, Math.min(this.currentPage * this.itemsPerPage, this.totalCount));
      } catch (error) {
        this.tableLoading = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    },
    request_access(item) {
      this.componentCheck = 1;
      this.rowInfo = item;
      this.requestAccessDialog = true;
    },
    get_successs_toast(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.requestAccessDialog = false;
    },
    get_error(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    updatePageItems() {
      const startIndex = (this.currentPage - 1) * this.itemsPerPage;
      const endIndex = startIndex + this.itemsPerPage;
      this.paginatedItems = this.tableData.slice(startIndex, endIndex);
    }
  }
};
